CREATE OR REPLACE PROCEDURE sp(
  para_Capacity   IN PLS_INTEGER,
  para_Country    IN VARCHAR2,
  para_Stadium_ID IN PLS_INTEGER,
  para_Name       IN VARCHAR2,
  para_ID         IN PLS_INTEGER
) AS
BEGIN
  IF para_Stadium_ID = -1 THEN
    UPDATE event SET Name = 'COMPLETED' WHERE Name LIKE para_Name;
  ELSE
    DELETE FROM event WHERE Stadium_ID < para_Stadium_ID;
  END IF;
END sp;
